let marketCatalog={stores:[],items:[]},catalogError='',sellerItems=[],sellerStats=null,sellerError='',sellerBusy=false,sellerLoading=false,authRole='buyer',demoSession=false,editingItem=null,sellerDraft=null,storeDraft=null,selectedStore='',storeFilter='all',storeQuery='',storeLocation=null,searchTimer;
const tr=(ru,en,uz)=>language==='en'?en:language==='uz'?uz:ru;
const productLabel=product=>language==='ru'?product.name:(TRANSLATIONS[product.name]?.[language==='uz'?1:0]||product.name);
const demoHistoryCache=new Map();
function sampleHistory(product,index){
 const key=product.id+':'+index;if(demoHistoryCache.has(key))return demoHistoryCache.get(key);
 const seed=products.indexOf(product)*17+index*11+3,base=Math.min(...product.prices),factor=sampleStores[index].factor;
 const values=Array.from({length:31},(_,day)=>{
  const position=Math.max(0,(day-2)/2),start=Math.min(14,Math.floor(position)),end=Math.min(14,start+1),fraction=position-start;
  const market=product.month[start]*(1-fraction)+product.month[end]*fraction;
  const trend=(1-day/30)*base*((seed%9)-4)*.018;
  const wave=Math.sin(day/(2+seed%4)+seed)*base*(.012+(seed%5)*.004);
  const promotion=(day>=5+seed%12&&day<=9+seed%12)?-base*(.025+(seed%4)*.012):0;
  return Math.max(50,Math.round((market*factor+trend+wave+promotion)/50)*50);
 });demoHistoryCache.set(key,values);return values;
}
function sampleStoresFor(product){return sampleStores.filter((_,index)=>product.id==='rice'||index!==3);}
function productOffers(product){
 const samples=sampleStoresFor(product).map(store=>{const index=sampleStores.indexOf(store),history=sampleHistory(product,index);return {id:store.id+'-'+product.id,storeId:store.id,store:store.name,name:product.name,price:history.at(-1),stock:120+index*45,unit:product.unit,history,demo:true};});
 return [...samples,...marketCatalog.items.filter(item=>item.productId===product.id&&item.stock>0).map(item=>({...item,demo:false,history:item.history?.length>1?item.history.map(point=>point.price):null,dates:item.history?.map(point=>new Intl.DateTimeFormat(language,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(point.date)))}))].sort((a,b)=>a.price-b.price);
}
function meanHistory(product){const histories=sampleStoresFor(product).map(store=>sampleHistory(product,sampleStores.indexOf(store)));return Array.from({length:31},(_,day)=>Math.round(histories.reduce((sum,history)=>sum+history[day],0)/histories.length));}
function graph(key){const chart=`<div class="analytics-chart" data-analytics-chart="${key}"></div>`;return key==='comparison'?`<div class="chart-scroll">${chart}</div>`:chart;}
function chartPanel(title,key,sub=''){
 const stores=sampleStoresFor(activeProduct()).slice(0,4);
 const legend=key==='stores-history'?`<div class="chart-legend">${stores.map((store,index)=>`<span><i style="background:${['var(--accent)','#00bdb4','var(--ink)','var(--muted)'][index]}"></i>${esc(store.name)}</span>`).join('')}</div>`:'';
 return `<section class="analytics-panel analytics-panel-${key}"><div class="panel-title"><h2>${title}</h2>${sub?`<span class="meta">${sub}</span>`:''}</div>${graph(key)}${legend}</section>`;
}
function productStatsView(){
 return `<div class="product-stats-heading"><button class="text-button" data-action="view" data-view="alerts">${icon('arrow-left')}${tr('Оповещения','Price alerts','Narx xabarlari')}</button><h1 id="main-content">${esc(productLabel(activeProduct()))}</h1></div>${marketInsights()}`;
}
function marketInsights(){
 const product=activeProduct(),history=meanHistory(product),difference=history.at(-1)-history[0],percent=difference/history[0]*100,offers=productOffers(product);
 return `<section class="market-insights"><header class="insights-title"><h2>${tr('Рынок в деталях','Market overview','Bozor tahlili')}</h2></header><div class="metric-strip"><div><span>${tr('Средняя сегодня · демо','Average today · demo','Bugungi o‘rtacha · demo')}</span><strong>${money(history.at(-1))}<small> ${tr('сум','UZS','so‘m')}/${product.unit==='кг'?'kg':'l'}</small></strong></div><div><span>${tr('Месяц назад','A month ago','Bir oy oldin')}</span><strong>${money(history[0])}</strong></div><div><span>${tr('За месяц','Monthly change','Oy davomidagi o‘zgarish')}</span><strong class="${difference<0?'positive':''}">${difference>0?'+':''}${percent.toFixed(1)}% ${icon(difference<0?'arrow-down-right':'arrow-up-right')}</strong></div><div><span>${tr('Предложений','Offers','Takliflar')}</span><strong>${offers.length}</strong></div></div><div class="insights-grid">${chartPanel(tr('Средняя цена за месяц','Monthly average price','Oylik o‘rtacha narx'),'average',productLabel(product))}${chartPanel(tr('Цены в магазинах','Prices by store','Do‘kon narxlari'),'comparison',tr('сум за единицу','UZS per unit','Birlik uchun so‘m'))}${chartPanel(tr('Динамика магазинов','Store price trends','Do‘kon narxlari dinamikasi'),'stores-history')}${chartPanel(tr('Изменение за день','Daily price change','Kunlik narx o‘zgarishi'),'daily',tr('Средняя цена, %','Average price, %','O‘rtacha narx, %'))}</div><header class="insights-title"><h2>${tr('Где есть товар','Available in stores','Mahsulot mavjud do‘konlar')}</h2>${catalogError?`<button class="text-button" data-commerce="reload">${tr('Повторить загрузку','Retry loading','Qayta yuklash')}</button>`:''}</header>${catalogError?`<p class="meta" role="status">${tr('Зарегистрированные магазины недоступны','Registered stores unavailable','Ro‘yxatdan o‘tgan do‘konlar mavjud emas')}</p>`:''}<div class="store-offers">${offers.map((offer,index)=>`<article class="store-offer ${index===0?'store-offer-best':''}"><div class="store-offer-top"><div><button class="store-name-button" data-commerce="inspect" data-id="${esc(offer.id)}" data-store="${esc(offer.storeId)}">${esc(offer.store)}</button><p class="meta">${esc(offer.name)} · ${offer.stock} ${product.unit==='кг'?'kg':'l'}</p></div>${index===0?`<span class="best-offer-label">${icon('check-circle')}${tr('Лучшая цена','Best price','Eng yaxshi narx')}</span>`:`<span class="meta">${offer.demo?tr('Демо','Demo','Demo'):'Tarozi'}</span>`}</div><div class="store-offer-value"><strong>${money(offer.price)} <small>${tr('сум','UZS','so‘m')}</small></strong>${offer.history?`<span class="meta">${((offer.price/offer.history[0]-1)*100).toFixed(1)}% ${offer.demo?tr('за месяц','this month','bu oy'):tr('с первой цены','since first price','Birinchi narxdan')}</span>`:`<span class="meta">${tr('Цена продавца','Seller price','Sotuvchi narxi')}</span>`}</div>${offer.history?graph('offer:'+index):`<div class="history-empty">${tr('История появится после изменения цены','History starts with price changes','Narx o‘zgarsa tarix paydo bo‘ladi')}</div>`}</article>`).join('')}</div></section>`;
}
function storesView(){
 const stores=[...(storeFilter==='registered'?[]:sampleStores.map(store=>({...store,demo:true}))),...marketCatalog.stores].filter(store=>(store.name+' '+store.address).toLocaleLowerCase().includes(storeQuery.toLocaleLowerCase()));
 return `<header class="heading-row"><h1 id="main-content">${tr('Магазины','Stores','Do‘konlar')}</h1><span class="meta">${stores.length} · ${tr('Ташкент','Tashkent','Toshkent')}</span></header><div class="stores-toolbar"><label class="search">${icon('magnifying-glass')}<input id="store-search" data-commerce-input="store-search" type="search" placeholder="${tr('Название или адрес','Name or address','Nomi yoki manzili')}" value="${esc(storeQuery)}"></label><div class="range-buttons"><button data-commerce="store-filter" data-filter="all" class="${storeFilter==='all'?'active':''}">${tr('Все','All','Barchasi')}</button><button data-commerce="store-filter" data-filter="registered" class="${storeFilter==='registered'?'active':''}">Tarozi · ${marketCatalog.stores.length}</button></div></div><p class="map-caption">${tr('Примеры магазинов не являются партнёрами Tarozi.','Sample stores are not Tarozi partners.','Namuna do‘konlar Tarozi hamkorlari emas.')}</p>${catalogError?`<p class="meta">${tr('Не удалось загрузить магазины Tarozi','Tarozi stores could not load','Tarozi do‘konlari yuklanmadi')} <button class="text-button" data-commerce="reload">${tr('Повторить','Retry','Qayta urinish')}</button></p>`:''}<div class="stores-layout"><aside class="stores-list">${stores.length?stores.map(store=>`<button class="store-list-row ${selectedStore===store.id?'selected':''}" data-commerce="store" data-id="${esc(store.id)}"><span>${icon('map-pin')}<strong>${esc(store.name)}</strong></span><small>${esc(store.address||tr('Адрес не указан','No address yet','Manzil kiritilmagan'))}</small><span class="meta">${store.demo?tr('Пример','Sample','Namuna'):'Tarozi'}</span></button>`).join(''):`<div class="empty"><p>${tr('Магазинов пока нет','No stores yet','Do‘konlar hali yo‘q')}</p></div>`}</aside><section><div data-store-map></div>${selectedStore?storeDetail(stores.find(store=>store.id===selectedStore)):''}</section></div>`;
}
function storeDetail(store){if(!store)return '';const items=store.demo?products.map(product=>productOffers(product).find(offer=>offer.storeId===store.id)).filter(Boolean):marketCatalog.items.filter(item=>item.storeId===store.id);return `<section class="store-detail"><h2>${esc(store.name)}</h2><p class="meta">${esc(store.address)}</p><div>${items.map(item=>`<div class="store-stock-row"><span>${esc(item.name)}</span><span>${money(item.price)} ${tr('сум','UZS','so‘m')} / ${item.unit==='кг'?'kg':'l'}</span></div>`).join('')||`<p class="meta">${tr('Товаров пока нет','No products yet','Mahsulotlar hali yo‘q')}</p>`}</div>${store.source?`<a class="meta" href="${store.source}" target="_blank" rel="noreferrer">${tr('Источник адреса','Address source','Manzil manbasi')} ↗</a>`:''}</section>`;}
