function mountCommerce(){
 const stores=[...(storeFilter==='registered'?[]:sampleStores),...marketCatalog.stores].filter(store=>(store.name+' '+store.address).toLowerCase().includes(storeQuery.toLowerCase()));
 document.querySelectorAll('[data-store-map]').forEach(element=>Charts.map(element,{stores:stores.filter(store=>Number.isFinite(store.lat)&&Number.isFinite(store.lng)),selected:selectedStore,language,marker:icon('storefront')}));
 document.querySelectorAll('[data-store-picker]').forEach(element=>Charts.map(element,{stores:storeLocation?[{id:'own',name:profile.store||profile.name,...storeLocation}]:Number.isFinite(profile?.lat)?[{id:'own',name:profile.store||profile.name,lat:profile.lat,lng:profile.lng}]:[],picker:true,language,marker:icon('storefront')}));
 drawInsightCharts();
}
function drawInsightCharts(){
 const product=activeProduct(),history=meanHistory(product),offers=productOffers(product),dates=history.map((_,index)=>String(index+1)+' '+tr('окт','Oct','okt')),unit=tr('сум','UZS','so‘m');
 const definitions={average:{type:'area',labels:dates,series:[{name:tr('Средняя','Average','O‘rtacha'),values:history}]},comparison:{type:'horizontal-bar',highlightIndex:0,labels:offers.map(offer=>offer.store.replace('Korzinka · ','')),series:[{name:tr('Цена','Price','Narx'),values:offers.map(offer=>offer.price)}]},'stores-history':{labels:dates,series:sampleStoresFor(product).slice(0,4).map(store=>({name:store.name,values:sampleHistory(product,sampleStores.indexOf(store))}))},daily:{type:'bar',unit:'%',labels:dates.slice(1),series:[{name:tr('Изменение','Change','O‘zgarish'),values:history.slice(1).map((value,index)=>Number(((value/history[index]-1)*100).toFixed(2)))}]},demand:{type:'bar',unit:'',labels:products.map(product=>language==='ru'?product.short:productLabel(product)),series:[{name:tr('Поиски','Searches','Qidiruvlar'),values:products.map(product=>sellerStats?.demand.find(row=>row.productId===product.id)?.count||0)}]},searches:{unit:'',labels:sellerStats?.days.map(day=>day.slice(5))||[''],series:[{name:tr('Поиски','Searches','Qidiruvlar'),values:sellerStats?.searches||[0]}]},views:{unit:'',labels:sellerStats?.days.map(day=>day.slice(5))||[''],series:[{name:tr('Просмотры','Views','Ko‘rishlar'),values:sellerStats?.views||[0]}]},'market-prices':{type:'bar',labels:products.map(product=>language==='ru'?product.short:productLabel(product)),series:[{name:tr('Средняя цена','Average price','O‘rtacha narx'),values:products.map(product=>meanHistory(product).at(-1))}]}};
 document.querySelectorAll('[data-analytics-chart]').forEach(element=>{if(element.dataset.drawn)return;const key=element.dataset.analyticsChart;let options=definitions[key];if(key.startsWith('offer:')){const offer=offers[Number(key.split(':')[1])];options={type:'area',labels:offer.dates||dates,series:[{name:offer.store,values:offer.history}]};}if(!options)return;element.dataset.drawn='true';if(key==='comparison')element.style.height=Math.max(310,offers.length*25+35)+'px';Charts.line(element,{locale:language,unit,type:'line',yTicks:[],...options});});
}
async function loadCatalog(){try{if(demoSession){marketCatalog={stores:[],items:[]};catalogError='';}else{const response=await fetch('/api/market/catalog');if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.items)||!Array.isArray(data.stores))throw Error();marketCatalog=data;catalogError='';}}catch{catalogError='unavailable';}if(demoSession){const items=readDemoItems(),store=readDemoStore();marketCatalog.items=[...marketCatalog.items.filter(item=>item.storeId!=='demo-seller'),...items.filter(item=>item.stock>0).map(item=>({...item,storeId:'demo-seller',store:store.store||tr('Демо-магазин','Demo store','Demo do‘kon')}))];marketCatalog.stores.push({id:'demo-seller',name:store.store||tr('Демо-магазин','Demo store','Demo do‘kon'),address:store.address||'',lat:store.lat,lng:store.lng});}refresh();}
function readDemoStore(){try{return JSON.parse(localStorage.getItem('tarozi-demo-store')||'{}');}catch{return {};}}
function readDemoItems(){try{return JSON.parse(localStorage.getItem('tarozi-demo-items')||'[]');}catch{return [];}}
async function loadSeller(){sellerLoading=true;sellerError='';refresh();try{if(demoSession){sellerItems=readDemoItems();sellerStats=demoAnalytics();}else{const results=await Promise.all(['/api/seller/items','/api/seller/analytics'].map(async url=>{const response=await fetch(url,{credentials:'same-origin'});if(!response.ok)throw Error();return response.json();}));sellerItems=results[0].items;sellerStats=results[1];}}catch{sellerError=tr('Не удалось загрузить данные','Could not load data','Ma’lumot yuklanmadi');}finally{sellerLoading=false;refresh();}}
function recordMarketEvent(data){if(demoSession){let events;try{events=JSON.parse(localStorage.getItem('tarozi-demo-events')||'[]');}catch{events=[];}events.push({...data,day:new Date().toISOString().slice(0,10)});localStorage.setItem('tarozi-demo-events',JSON.stringify(events.slice(-5000)));return;}fetch('/api/market/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).catch(()=>{});}
document.addEventListener('tarozi:store',event=>{selectedStore=event.detail.id;refresh();});
document.addEventListener('tarozi:location',event=>{storeLocation=event.detail;const status=document.getElementById('location-status');if(status)status.textContent=tr('Место выбрано','Location selected','Joy tanlandi');});
document.addEventListener('input',event=>{
 if(event.target.dataset.commerceInput==='store-search'){storeQuery=event.target.value;refresh();}
 if(event.target.dataset.input==='search'){clearTimeout(searchTimer);const query=event.target.value.trim();searchTimer=setTimeout(()=>{if(query&&profile)visibleProducts().forEach(product=>recordMarketEvent({type:'search',productId:product.id}));},650);}
});
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-commerce]');if(!button)return;
 const action=button.dataset.commerce;
 if(action==='role'){authRole=button.dataset.role;refresh();}
 if(action==='demo'){demoSession=true;profile={...readDemoStore(),id:authRole==='seller'?'demo-seller':'demo-buyer',name:authRole==='seller'?tr('Мой магазин','My store','Do‘konim'):tr('Покупатель','Buyer','Xaridor'),role:authRole,provider:'demo',email:''};state.page=authRole==='seller'?'seller':'market';loadCatalog();if(authRole==='seller')loadSeller();refresh();}
 if(action==='seller-reload')loadSeller();
 if(action==='seller-tab'){state.sellerTab=button.dataset.tab;refresh();}
 if(action==='store'){selectedStore=button.dataset.id;refresh();}
 if(action==='store-filter'){storeFilter=button.dataset.filter;selectedStore='';refresh();}
 if(action==='edit-item'){editingItem=button.dataset.id;sellerDraft=null;refresh();}
 if(action==='new-item'){editingItem=null;sellerDraft=null;refresh();}
 if(action==='reload')loadCatalog();
 if(action==='inspect'){const item=marketCatalog.items.find(item=>item.id===button.dataset.id);if(item)recordMarketEvent({type:'view',productId:item.productId,itemId:item.id});selectedStore=button.dataset.store;state.page='stores';refresh();}
});
document.addEventListener('submit',async event=>{
 if(!['seller-product-form','seller-store-form'].includes(event.target.id))return;event.preventDefault();if(sellerBusy)return;
 const form=event.target,formId=form.id,data=Object.fromEntries(new FormData(form));sellerBusy=true;sellerError='';
 form.querySelectorAll('button').forEach(button=>button.disabled=true);
 try{
  if(formId==='seller-product-form'){
   data.price=Number(data.price);data.stock=Number(data.stock);sellerDraft=data;if(editingItem)data.id=editingItem;
   if(demoSession){const items=readDemoItems(),item={...data,id:editingItem||crypto.randomUUID(),unit:byId(data.productId).unit};const index=items.findIndex(row=>row.id===item.id),previous=items[index];item.history=previous?.productId===item.productId?previous.history||[]:[];if(previous?.price!==item.price)item.history.push({date:new Date().toISOString(),price:item.price});if(index>=0)items[index]=item;else items.push(item);localStorage.setItem('tarozi-demo-items',JSON.stringify(items));}else await accountRequest('/api/seller/items',data);
   editingItem=null;sellerDraft=null;
  }else{
   storeDraft=data;
   const point=storeLocation||(Number.isFinite(profile.lat)?{lat:profile.lat,lng:profile.lng}:null);if(!point)throw Error('LOCATION_REQUIRED');Object.assign(data,point);
   if(demoSession){Object.assign(profile,data);localStorage.setItem('tarozi-demo-store',JSON.stringify(data));}else {const result=await accountRequest('/api/seller/store',data);Object.assign(profile,data,{store:result.store.name});}
  }
  storeDraft=null;await loadCatalog();await loadSeller();document.getElementById('announcer').textContent=tr('Сохранено','Saved','Saqlandi');
 }catch(error){sellerError=error.message==='LOCATION_REQUIRED'?tr('Выберите место на карте','Choose a location on the map','Xaritadan joy tanlang'):tr('Не удалось сохранить','Could not save','Saqlab bo‘lmadi');}finally{sellerBusy=false;refresh();}
});

function demoAnalytics(){
 const days=Array.from({length:30},(_,index)=>new Date(Date.now()-(29-index)*86400000).toISOString().slice(0,10));let events=[];try{events=JSON.parse(localStorage.getItem('tarozi-demo-events')||'[]').filter(event=>event.day>=days[0]);}catch{}
 return {days,searches:days.map(day=>events.filter(event=>event.day===day&&event.type==='search').length),views:days.map(day=>events.filter(event=>event.day===day&&event.type==='view').length),demand:products.map(product=>({productId:product.id,count:events.filter(event=>event.productId===product.id&&event.type==='search').length})),items:sellerItems.map(item=>({id:item.id,views:events.filter(event=>event.itemId===item.id&&event.type==='view').length}))};
}
